-- 0023_topic_grades
--
-- One topic per curriculum concept; the grades it is taught at move to
-- `topic_grades` (design doc 2026-09-03-taxonomy-topic-grades-design.md,
-- audit 2026-09-03-taxonomy-data-audit.md).
--
-- Schema change AND data collapse in ONE file on purpose: prod runs
-- `migrate && seed && main` (infra/docker-compose.dokploy.yml), the drizzle
-- migrator wraps every pending migration in a single transaction
-- (drizzle-orm/pg-core/dialect.js), and there is no manual step to forget.
-- Irreversible except from the `pg_dump` taken before deploy.
--
-- Generated by `drizzle-kit generate` and then hand-edited: every DDL block
-- below is the generated one verbatim, only reordered so the data collapse
-- runs between the new table and the drop of `topics.grade_level` — the
-- collapse reads that column. `migration-snapshot.spec.ts` still passes: it
-- regenerates against `meta/0023_snapshot.json`, finds no schema drift, and so
-- compares this file against itself.

-- Pre-flight. Collapsing merges rows by `(course_id, name)`, so two DIFFERENT
-- names that share one non-null `slug` inside a course survive as two rows and
-- then fail `topics_course_id_slug_idx` at the bottom of this file with
-- Postgres' generic "could not create unique index" — which says nothing about
-- what to fix. This does not happen in any known database (the seeder derives
-- the slug from the canonical name), so the check is cheap insurance whose only
-- job is to name the offending rows if it ever does.
DO $$
DECLARE
  offender text;
BEGIN
  SELECT format(
           'course_id=%s slug=%s names=[%s]',
           t."course_id", t."slug", string_agg(DISTINCT t."name", ' | ')
         )
    INTO offender
    FROM "topics" t
   WHERE t."slug" IS NOT NULL
   GROUP BY t."course_id", t."slug"
  HAVING count(DISTINCT t."name") > 1
   LIMIT 1;

  IF offender IS NOT NULL THEN
    RAISE EXCEPTION
      '0023_topic_grades: two topics in one course share a slug under different names (%). Reconcile them into one name before migrating.',
      offender;
  END IF;
END $$;
--> statement-breakpoint

CREATE TABLE IF NOT EXISTS "topic_grades" (
	"topic_id" uuid NOT NULL,
	"grade_level" text NOT NULL,
	CONSTRAINT "topic_grades_topic_id_grade_level_pk" PRIMARY KEY("topic_id","grade_level")
);
--> statement-breakpoint
DO $$ BEGIN
 ALTER TABLE "topic_grades" ADD CONSTRAINT "topic_grades_topic_id_topics_id_fk" FOREIGN KEY ("topic_id") REFERENCES "public"."topics"("id") ON DELETE cascade ON UPDATE no action;
EXCEPTION
 WHEN duplicate_object THEN null;
END $$;
--> statement-breakpoint
DO $$ BEGIN
 ALTER TABLE "topic_grades" ADD CONSTRAINT "topic_grades_grade_level_grade_levels_code_fk" FOREIGN KEY ("grade_level") REFERENCES "public"."grade_levels"("code") ON DELETE no action ON UPDATE no action;
EXCEPTION
 WHEN duplicate_object THEN null;
END $$;
--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "topic_grades_grade_level_idx" ON "topic_grades" USING btree ("grade_level");--> statement-breakpoint

-- The canonical row of every `(course_id, name)` group: the copy whose grade
-- has the lowest `grade_levels.sort_order`, id as the tie-break. `topics` has
-- no `created_at`, so id IS the tie-break (the design doc's "created_at/id"
-- collapses to id). Grade-less rows sort last via the COALESCE sentinel, so a
-- NULL-grade copy inside an otherwise graded group is collapsed INTO it and
-- contributes no `topic_grades` row.
-- TEMP + ON COMMIT DROP: the migrator holds one connection for the whole
-- transaction, and the table must not survive it.
CREATE TEMP TABLE "topic_collapse_map" ON COMMIT DROP AS
SELECT
  t."id" AS copy_id,
  first_value(t."id") OVER (
    PARTITION BY t."course_id", t."name"
    ORDER BY COALESCE(g."sort_order", 2147483647), t."id"
  ) AS canonical_id
FROM "topics" t
LEFT JOIN "grade_levels" g ON g."code" = t."grade_level";
--> statement-breakpoint
CREATE UNIQUE INDEX ON "topic_collapse_map" (copy_id);
--> statement-breakpoint

-- Lift a slug onto a canonical row that has none. The copies are deleted a few
-- statements below, and with them any `slug` only THEY carried — the seeder
-- wrote the slug per copy, so which of a group's rows holds it is an accident
-- of the old (course_id, slug, grade_level) uniqueness, not a decision.
--
-- Why it matters beyond tidiness: `reconcileLegacyTopics` (db/seed) treats a
-- preuniversitario topic with no slug as a legacy row and either throws or
-- deletes it on the very next `seed()` — and prod runs `migrate && seed &&
-- main`. Losing the slug here is therefore not cosmetic; it is the next boot.
--
-- It cannot collide with `topics_course_id_slug_idx` (created at the bottom of
-- this file, unique on (course_id, slug) where slug is not null):
--   * inside the group, DISTINCT ON picks exactly ONE donor slug per canonical
--     row, and only rows that have none are written;
--   * across groups, a slug shared by two DIFFERENT names in one course is
--     precisely what the pre-flight check above refuses to migrate, and the old
--     unique (course_id, slug, grade_level) allowed that shape ONLY across
--     different grades — which is what the pre-flight scans for.
-- Donor tie-break is the copy's id, so a restored dump migrates identically.
UPDATE "topics" t
SET "slug" = src.slug
FROM (
  SELECT DISTINCT ON (m.canonical_id) m.canonical_id, c."slug"
  FROM "topic_collapse_map" m
  JOIN "topics" c ON c."id" = m.copy_id
  WHERE c."slug" IS NOT NULL
  ORDER BY m.canonical_id, c."id"
) src
WHERE t."id" = src.canonical_id AND t."slug" IS NULL;
--> statement-breakpoint

-- Every grade any copy of the group carried becomes a row on the canonical
-- topic. A group whose every copy has a NULL grade ends up with no rows —
-- "taught across the whole stage".
INSERT INTO "topic_grades" ("topic_id", "grade_level")
SELECT DISTINCT m.canonical_id, t."grade_level"
FROM "topics" t
JOIN "topic_collapse_map" m ON m.copy_id = t."id"
WHERE t."grade_level" IS NOT NULL
ON CONFLICT DO NOTHING;
--> statement-breakpoint

