-- Folders. Per tenant, several seeded folders can point at copies of one
-- group; the survivor is the lowest `position` (id as tie-break), and the
-- others hand it their questions and their children before being deleted.
-- `question_folders_tenant_topic_idx` (partial unique on tenant_id, topic_id)
-- is why they cannot simply be repointed.
CREATE TEMP TABLE "folder_merge_map" ON COMMIT DROP AS
SELECT
  f."id" AS loser_id,
  first_value(f."id") OVER (
    PARTITION BY f."tenant_id", m.canonical_id
    ORDER BY f."position", f."id"
  ) AS keeper_id
FROM "question_folders" f
JOIN "topic_collapse_map" m ON m.copy_id = f."topic_id";
--> statement-breakpoint
CREATE UNIQUE INDEX ON "folder_merge_map" (loser_id);
--> statement-breakpoint

-- Both remaining folder steps (re-parenting a loser's children under the
-- keeper, and stripping the seeded ` · <label>` suffix) can land two folders
-- on the same name inside one parent, and
-- `question_folders_sibling_name_idx` / `question_folders_root_name_idx` are
-- plain unique indexes: NOT DEFERRABLE, checked per row as the statement
-- writes it. So the name a folder ENDS UP with has to be decided in the very
-- same statement that moves or renames it — a "fix the duplicates afterwards"
-- pass never runs, because the transaction has already aborted.
--
-- This table is that statement's input: the folders to touch, where each one
-- is going, and the name it WANTS. `apply_folder_rename_plan()` turns the
-- wanted name into a free one and applies both columns at once. Written as a
-- temp function rather than twice inline because getting this right once is
-- hard enough; dropped again below.
CREATE TEMP TABLE "folder_rename_input" (
  "id" uuid PRIMARY KEY,
  "tenant_id" uuid NOT NULL,
  "new_parent_id" uuid,
  "base_name" text NOT NULL,
  "position" integer NOT NULL
) ON COMMIT DROP;
--> statement-breakpoint
-- The decision is materialised here rather than applied straight from the CTE
-- so that "every planned folder actually got a name" can be CHECKED before a
-- single row moves. Created outside the function, once, because a temp table
-- created inside a plpgsql body gets a new OID on every call while the body's
-- cached plans keep pointing at the old one.
CREATE TEMP TABLE "folder_rename_assignment" (
  "id" uuid PRIMARY KEY,
  "new_parent_id" uuid,
  "final_name" text NOT NULL
) ON COMMIT DROP;
--> statement-breakpoint
CREATE FUNCTION pg_temp.apply_folder_rename_plan() RETURNS void LANGUAGE plpgsql AS $fn$
DECLARE
  unplaced text;
BEGIN
  INSERT INTO "folder_rename_assignment" ("id", "new_parent_id", "final_name")
  WITH plan AS (
    SELECT
      i."id",
      i."tenant_id",
      i."new_parent_id",
      -- Root folders have a NULL parent and are deduped by
      -- `question_folders_root_name_idx`, so NULL is a group like any other.
      COALESCE(i."new_parent_id", '00000000-0000-0000-0000-000000000000'::uuid) AS grp,
      left(i."base_name", 80) AS base_name,
      -- The name with any trailing " (2)", " (3)" … taken off, which is what
      -- the numbered candidates below are built from. Numbering "Foo (2)" as
      -- "Foo (2) (2)" would be silly on its own, but the real reason is
      -- arithmetic: `dedupeSiblingNames` produces names of EXACTLY 80
      -- characters ending in " (n)", and cutting four characters off one of
      -- those to append " (n)" hands back the very string it started from.
      -- Stripping first makes every candidate provably distinct (see below).
      COALESCE(
        NULLIF(regexp_replace(left(i."base_name", 80), '( \(\d+\))+$', ''), ''),
        left(i."base_name", 80)
      ) AS stem,
      i."position"
    FROM "folder_rename_input" i
  ),
  -- Names the destination group ALREADY holds. Rows in the plan are excluded:
  -- their current name is about to be replaced, so it is not an obstacle.
  -- Losers still count — they are deleted only after this runs, so their names
  -- genuinely occupy the index right now.
  taken AS (
    SELECT DISTINCT p."tenant_id", p.grp, e."name"
    FROM plan p
    JOIN "question_folders" e
      ON e."tenant_id" = p."tenant_id"
     AND COALESCE(e."parent_id", '00000000-0000-0000-0000-000000000000'::uuid) = p.grp
    WHERE NOT EXISTS (SELECT 1 FROM plan p2 WHERE p2."id" = e."id")
  ),
  -- Who gets the bare name when several folders want the same one: seed order
  -- (`position`), id as the tie-break. Ordering by id alone would hand it to
  -- whichever random uuid sorted first, which is neither meaningful to a
  -- teacher looking at her tree nor reproducible from a restored dump.
  ranked AS (
    SELECT
      p.*,
      row_number() OVER (
        PARTITION BY p."tenant_id", p.grp, p.base_name
        ORDER BY p."position", p."id"
      ) AS rn
    FROM plan p
  ),
  families AS (
    SELECT
      r."tenant_id",
      r.grp,
      r.base_name,
      r.stem,
      max(r.rn) AS needed,
      (SELECT count(*) FROM taken t WHERE t."tenant_id" = r."tenant_id" AND t.grp = r.grp) AS blocked,
      (SELECT count(DISTINCT o.base_name) FROM plan o
        WHERE o."tenant_id" = r."tenant_id" AND o.grp = r.grp AND o.base_name <> r.base_name) AS rival
    FROM ranked r
    GROUP BY r."tenant_id", r.grp, r.base_name, r.stem
  ),
  -- The name the folder asked for, then "<stem> (2)", "<stem> (3)", … each
  -- clamped to the 80 characters `MAX_FOLDER_NAME_LENGTH` allows.
  --
  -- DISTINCTNESS. Every numbered candidate ends in " (n)", and a string has at
  -- most one trailing ` \(\d+\)`, so two numbered candidates with different n
  -- are different strings. The stem has had its own trailing " (n)" removed, so
  -- candidate 1 carries no such suffix and cannot equal a numbered one either —
  -- EXCEPT when the folder's own name already was "<stem> (n)", in which case
  -- candidate 1 and candidate n are the same string; the DISTINCT ON below
  -- collapses that one pair and keeps the earlier ordinal. Building the
  -- numbered forms from `base_name` instead of `stem` was what produced
  -- duplicates: an 80-character "<76 chars> (2)" cut to 76 and given " (2)"
  -- back is itself, so the family could run dry and abort the deploy.
  --
  -- BUDGET. `free` rejects a candidate for exactly two reasons: it is one of
  -- the `blocked` names the destination group already holds, or one of the
  -- `rival` base names another family is claiming in that group. Each rejection
  -- consumes one of those distinct names, and at most one candidate is lost to
  -- the DISTINCT ON above, so `needed + blocked + rival + 1` generated forms
  -- always leave at least `needed` free ones.
  candidates AS (
    SELECT DISTINCT ON (f."tenant_id", f.grp, f.base_name, cand.candidate)
      f."tenant_id",
      f.grp,
      f.base_name,
      cand.i,
      cand.candidate
    FROM families f
    CROSS JOIN LATERAL (
      SELECT
        s.i,
        CASE
          WHEN s.i = 1 THEN f.base_name
          ELSE left(f.stem, 80 - length(' (' || s.i || ')')) || ' (' || s.i || ')'
        END AS candidate
      FROM generate_series(1, f.needed + f.blocked + f.rival + 1) AS s(i)
    ) cand
    ORDER BY f."tenant_id", f.grp, f.base_name, cand.candidate, cand.i
  ),
  free AS (
    SELECT
      c."tenant_id",
      c.grp,
      c.base_name,
      c.candidate,
      row_number() OVER (PARTITION BY c."tenant_id", c.grp, c.base_name ORDER BY c.i) AS slot
    FROM candidates c
    WHERE NOT EXISTS (
            SELECT 1 FROM taken t
            WHERE t."tenant_id" = c."tenant_id" AND t.grp = c.grp AND t."name" = c.candidate
          )
      -- A folder literally named "Foo (2)" landing in the same group as "Foo"
      -- would otherwise both be handed "Foo (2)". The bare name always wins.
      AND NOT EXISTS (
            SELECT 1 FROM plan o
            WHERE o."tenant_id" = c."tenant_id"
              AND o.grp = c.grp
              AND o.base_name <> c.base_name
              AND o.base_name = c.candidate
          )
  )
  SELECT r."id", r."new_parent_id", fr.candidate
  FROM ranked r
  JOIN free fr
    ON fr."tenant_id" = r."tenant_id"
   AND fr.grp = r.grp
   AND fr.base_name = r.base_name
   AND fr.slot = r.rn;

  -- A folder with no name assigned would simply not be moved by the UPDATE
  -- below, stay parented to a folder this migration deletes, and be cascaded
  -- out of existence along with its subtree — data loss with no error anywhere.
  -- The budget above is meant to make this impossible; if the reasoning is ever
  -- wrong, the deploy stops here and says which folder.
  SELECT format(
           'folder %s (tenant %s, destination parent %s, wanted name %L)',
           i."id", i."tenant_id", COALESCE(i."new_parent_id"::text, '<root>'), i."base_name"
         )
    INTO unplaced
    FROM "folder_rename_input" i
   WHERE NOT EXISTS (
           SELECT 1 FROM "folder_rename_assignment" a WHERE a."id" = i."id"
         )
   LIMIT 1;

  IF unplaced IS NOT NULL THEN
    RAISE EXCEPTION
      '0023_topic_grades: ran out of free sibling names for % — refusing to leave it behind for the cascading delete.',
      unplaced;
  END IF;

  UPDATE "question_folders" f
  SET "parent_id" = a."new_parent_id",
      "name" = a."final_name"
  FROM "folder_rename_assignment" a
  WHERE f."id" = a."id";

  DELETE FROM "folder_rename_assignment";
  DELETE FROM "folder_rename_input";
END;
$fn$;
--> statement-breakpoint
UPDATE "questions" q
SET "folder_id" = fm.keeper_id
FROM "folder_merge_map" fm
WHERE fm.loser_id = q."folder_id" AND fm.keeper_id <> q."folder_id";
--> statement-breakpoint

-- Case 1: every child of a losing folder moves under the keeper, keeping its
-- own name where the keeper does not already have one like it.
--
-- The keeper itself can be one of those children (a seeded tree may nest the
-- grade folders). It obviously cannot become its own parent, and
-- `question_folders.parent_id` is ON DELETE CASCADE, so leaving it under the
-- loser would delete the keeper AND its whole subtree three statements from
-- now.
--
-- Where it goes instead cannot be read off the loser in one step. With a chain
-- `M -> L -> K` whose three folders all belong to ONE merge group and where K
-- is the keeper, "L's parent" is M, and M's keeper is K again — a one-step lift
-- makes K its own parent and the delete then orphans it. So the keeper WALKS UP
-- `parent_id` until it reaches an ancestor this statement leaves alone, or runs
-- out and becomes a root.
--
-- "Leaves alone" has to mean more than "does not delete". An ancestor that is
-- itself being re-parented can land anywhere — including inside the keeper's
-- own subtree, which closes a `parent_id` loop that no constraint forbids and
-- every recursive tree query in the app would hang on. The reviewer's shape:
-- `L'(root) -> A -> L -> K -> K2` with `{L', K2}` one merge group (K2 the
-- keeper) and `{L, K}` another (K the keeper). A moves under K2, K2 is K's own
-- child, so lifting K onto A gives K -> A -> K2 -> K. Skipping every unstable
-- ancestor walks K past A and past L' to the root instead.
--
-- `depth < 100` is a cycle brake, not a real limit: no tenant nests folders
-- anywhere near that deep, and without it corrupt data would spin here forever.
INSERT INTO "folder_rename_input" ("id", "tenant_id", "new_parent_id", "base_name", "position")
WITH RECURSIVE "unstable" AS (
  -- Deleted by the merge …
  SELECT loser_id AS id FROM "folder_merge_map" WHERE keeper_id <> loser_id
  UNION
  -- … or moved elsewhere by this very statement.
  SELECT moved."id"
  FROM "question_folders" moved
  JOIN "folder_merge_map" fm
    ON fm.loser_id = moved."parent_id" AND fm.keeper_id <> moved."parent_id"
),
"lift" AS (
  SELECT keeper."id" AS keeper_id, loser."parent_id" AS candidate, 0 AS depth
  FROM "question_folders" keeper
  JOIN "folder_merge_map" fm
    ON fm.loser_id = keeper."parent_id" AND fm.keeper_id <> keeper."parent_id"
  JOIN "question_folders" loser ON loser."id" = keeper."parent_id"
  WHERE keeper."id" = fm.keeper_id
  UNION ALL
  SELECT l.keeper_id, up."parent_id", l.depth + 1
  FROM "lift" l
  JOIN "question_folders" up ON up."id" = l.candidate
  WHERE l.depth < 100
    AND (l.candidate IN (SELECT id FROM "unstable") OR l.candidate = l.keeper_id)
),
"lifted" AS (
  SELECT DISTINCT ON (keeper_id) keeper_id, candidate
  FROM "lift"
  WHERE candidate IS NULL
     OR (candidate NOT IN (SELECT id FROM "unstable") AND candidate <> keeper_id)
  ORDER BY keeper_id, depth
)
SELECT
  f."id",
  f."tenant_id",
  CASE WHEN f."id" = fm.keeper_id THEN "lifted".candidate ELSE fm.keeper_id END,
  f."name",
  f."position"
FROM "question_folders" f
JOIN "folder_merge_map" fm ON fm.loser_id = f."parent_id" AND fm.keeper_id <> f."parent_id"
LEFT JOIN "lifted" ON "lifted".keeper_id = f."id";
--> statement-breakpoint
SELECT pg_temp.apply_folder_rename_plan();
--> statement-breakpoint

-- The only statement in this file that changes `parent_id` has just run. A
-- `parent_id` loop is not a constraint violation — Postgres would accept one
-- happily — but it makes the tenant's tree unwalkable: every recursive CTE in
-- the folders module would spin on it. The skip rule above is designed so this
-- cannot happen; this is the proof that it did not, and the deploy stops here
-- if the reasoning was ever wrong. 100 is a depth ceiling, not a real limit:
-- the seeder builds two levels and nothing in the app nests remotely that far.
DO $$
DECLARE
  offender uuid;
BEGIN
  WITH RECURSIVE walk AS (
    SELECT f."id" AS start_id, f."parent_id" AS node, 1 AS depth
    FROM "question_folders" f
    WHERE f."parent_id" IS NOT NULL
    UNION ALL
    SELECT w.start_id, up."parent_id", w.depth + 1
    FROM walk w
    JOIN "question_folders" up ON up."id" = w.node
    WHERE w.node <> w.start_id AND w.depth < 100
  )
  SELECT w.start_id INTO offender
  FROM walk w
  WHERE w.node = w.start_id OR w.depth >= 100
  LIMIT 1;

  IF offender IS NOT NULL THEN
    RAISE EXCEPTION
      '0023_topic_grades: re-parenting left folder % able to reach itself through parent_id (or nested past 100 levels) — refusing to commit an unwalkable tree.',
      offender;
  END IF;
END $$;
--> statement-breakpoint
DELETE FROM "question_folders" f
USING "folder_merge_map" fm
WHERE fm.loser_id = f."id" AND fm.keeper_id <> f."id";
--> statement-breakpoint
UPDATE "question_folders" f
SET "topic_id" = m.canonical_id
FROM "topic_collapse_map" m
WHERE m.copy_id = f."topic_id" AND m.canonical_id <> f."topic_id";
--> statement-breakpoint

-- Case 2, after case 1 so it sees the folders case 1 moved in: strip the
-- seeded ` · <grade label>` suffix. Matched against the TOPIC's own name
-- rather than a list of the 12 labels — a folder named exactly
-- "<topic name> · <anything>" is one the seeder wrote, and a folder the
-- teacher renamed by hand never matches, so her name survives.
INSERT INTO "folder_rename_input" ("id", "tenant_id", "new_parent_id", "base_name", "position")
SELECT f."id", f."tenant_id", f."parent_id", left(t."name", 80), f."position"
FROM "question_folders" f
JOIN "topics" t ON t."id" = f."topic_id"
WHERE f."name" <> left(t."name", 80)
  AND starts_with(f."name", t."name" || ' · ');
--> statement-breakpoint
SELECT pg_temp.apply_folder_rename_plan();
--> statement-breakpoint
